const ClaudeModelDiscoveryFreshnessWindow = 24 * time.Hour

var (
	claudeFullModelPattern         = regexp.MustCompile(`\bclaude-[a-z0-9][a-z0-9._-]*\b`)
	claudeFullFamilyVersionPattern = regexp.MustCompile(`\bclaude-(sonnet|opus|haiku)-([0-9]+)[.-]([0-9]{1,2})(?:\b|-)`)
	claudeFamilyVersionPattern     = regexp.MustCompile(`\b(?:claude\s+)?(sonnet|opus|haiku)\s+([0-9]+(?:[.-][0-9]+){0,2})\b`)
	claudeAliasPattern             = regexp.MustCompile(`(?m)(?:^|[\s'"])(sonnet|opus|haiku)(?:$|[\s'"])`)
	claudeEffortPattern            = regexp.MustCompile(`--effort\s+<level>.*\(([^)]*)\)`)
)

func DefaultClaudeModelDiscovery() harnesses.ModelDiscoverySnapshot {
	return harnesses.ModelDiscoverySnapshot{
		CapturedAt:      time.Now().UTC(),
		Models:          []string{"sonnet", "sonnet-4.6", "opus", "opus-4.7", "claude-sonnet-4-6"},
		ReasoningLevels: []string{"low", "medium", "high", "xhigh", "max"},
		Source:          "cli-help:claude",
		FreshnessWindow: ClaudeModelDiscoveryFreshnessWindow.String(),
		Detail:          "claude --help documents --model aliases/full IDs and --effort levels; authenticated PTY /model evidence refreshes family alias versions",
	}
}

func ReadClaudeModelDiscoveryViaPTY(timeout time.Duration, opts ...QuotaPTYOption) (harnesses.ModelDiscoverySnapshot, error) {
	cfg := quotaPTYOptions{binary: "claude"}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}
	var snapshot harnesses.ModelDiscoverySnapshot
	_, err := ptyquota.Run(context.Background(), ptyquota.Config{
		HarnessName:  "claude",
		Binary:       cfg.binary,
		Args:         cfg.args,
		Workdir:      cfg.workdir,
		Env:          cfg.env,
		Command:      "/model\r",
		ReadyMarkers: []string{"❯", "> "},
		DoneWhen:     claudeModelDiscoveryComplete,
		Timeout:      timeout,
		Size:         session.Size{Rows: 50, Cols: 220},
		CassetteDir:  cfg.cassetteDir,
		Discovery: func(text string) (cassette.DiscoveryRecord, error) {
			snapshot = claudeDiscoveryFromText(text, "pty")
			if len(snapshot.Models) == 0 {
				return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in claude /model output")
			}
			return discoveryRecord(snapshot), nil
		},
	})
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}, err
	}
	if len(snapshot.Models) == 0 {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in claude /model output")
	}
	return snapshot, nil
}

func ReadClaudeModelDiscoveryFromCassette(dir string) (harnesses.ModelDiscoverySnapshot, error) {
	reader, err := cassette.Open(dir)
	if err != nil {
		return harnesses.ModelDiscoverySnapshot{}, err
	}
	if rec := reader.Discovery(); rec != nil && len(rec.Models) > 0 {
		return snapshotFromDiscoveryRecord(*rec), nil
	}
	text := reader.Final().FinalText
	if text == "" {
		frames := reader.Frames()
		if len(frames) > 0 {
			text = strings.Join(frames[len(frames)-1].Text, "\n")
		}
	}
	snapshot := claudeDiscoveryFromText(text, "cassette")
	if len(snapshot.Models) == 0 {
		return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in claude model cassette")
	}
	return snapshot, nil
}

func ReadClaudeReasoningFromHelp(ctx context.Context, binary string, args ...string) ([]string, error) {
	if binary == "" {
		binary = "claude"
	}
	if len(args) == 0 {
		args = []string{"--help"}
	}
	cmd := exec.CommandContext(ctx, binary, args...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("claude help: %w", err)
	}
	levels := parseClaudeReasoningLevels(string(out))
	if len(levels) == 0 {
		return nil, fmt.Errorf("claude help did not expose --effort levels")
	}
	return levels, nil
}

func claudeModelDiscoveryComplete(text string) bool {
	return len(parseClaudeModels(text)) > 0
}

func claudeDiscoveryFromText(text, source string) harnesses.ModelDiscoverySnapshot {
	snapshot := DefaultClaudeModelDiscovery()
	if source != "" {
		snapshot.Source = source
	}
	if models := parseClaudeModels(text); len(models) > 0 {
		snapshot.Models = models
	}
	if levels := parseClaudeReasoningLevels(text); len(levels) > 0 {
		snapshot.ReasoningLevels = levels
	}
	return snapshot
}

func parseClaudeModels(text string) []string {
	text = stripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lower := strings.ToLower(text)
	models := uniqueMatches(claudeFullModelPattern.FindAllString(lower, -1))
	for _, match := range claudeFullFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 3 {
			models = appendUniqueString(models, match[1]+"-"+match[2]+"."+match[3])
		}
	}
	for _, match := range claudeFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 2 {
			models = appendUniqueString(models, match[1]+"-"+strings.ReplaceAll(match[2], "-", "."))
		}
	}
	for _, match := range claudeAliasPattern.FindAllStringSubmatch(lower, -1) {
		if len(match) > 1 {
			models = appendUniqueString(models, match[1])
		}
	}
	return models
}

func ResolveClaudeFamilyAlias(model string, snapshot harnesses.ModelDiscoverySnapshot) string {
	family := strings.ToLower(strings.TrimSpace(model))
	if family != "sonnet" && family != "opus" && family != "haiku" {
		return model
	}
	if resolved := latestClaudeFamilyVersion(family, snapshot.Models); resolved != "" {
		return resolved
	}
	return model
}

func latestClaudeFamilyVersion(family string, models []string) string {
	prefix := family + "-"
	best := ""
	var bestParts []int
	for _, model := range models {
		model = strings.ToLower(strings.TrimSpace(model))
		if !strings.HasPrefix(model, prefix) {
			continue
		}
		parts, ok := parseClaudeVersionParts(strings.TrimPrefix(model, prefix))
		if !ok {
			continue
		}
		if best == "" || compareVersionParts(parts, bestParts) > 0 {
			best = model
			bestParts = parts
		}
	}
	return best
}

func parseClaudeVersionParts(version string) ([]int, bool) {
	version = strings.ReplaceAll(version, "-", ".")
	raw := strings.Split(version, ".")
	if len(raw) == 0 {
		return nil, false
	}
	parts := make([]int, 0, len(raw))
	for _, part := range raw {
		if part == "" {
			return nil, false
		}
		n := 0
		for _, r := range part {
			if r < '0' || r > '9' {
				return nil, false
			}
			n = n*10 + int(r-'0')
		}
		parts = append(parts, n)
	}
	return parts, true
}

func compareVersionParts(a, b []int) int {
	n := len(a)
	if len(b) > n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		av, bv := 0, 0
		if i < len(a) {
			av = a[i]
		}
		if i < len(b) {
			bv = b[i]
		}
		if av > bv {
			return 1
		}
		if av < bv {
			return -1
		}
	}
	return 0
}

func parseClaudeReasoningLevels(text string) []string {
	text = stripANSI(strings.ReplaceAll(text, "\n", " "))
	m := claudeEffortPattern.FindStringSubmatch(text)
	if len(m) < 2 {
		return nil
	}
	parts := strings.Split(m[1], ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		out = appendUniqueString(out, strings.TrimSpace(part))
	}
	return out
}

func discoveryRecord(snapshot harnesses.ModelDiscoverySnapshot) cassette.DiscoveryRecord {
	return cassette.DiscoveryRecord{
		Source:            snapshot.Source,
		Status:            string(ptyquota.StatusOK),
		Models:            append([]string(nil), snapshot.Models...),
		ReasoningLevels:   append([]string(nil), snapshot.ReasoningLevels...),
		CapturedAt:        snapshot.CapturedAt.UTC().Format(time.RFC3339),
		FreshnessWindow:   snapshot.FreshnessWindow,
		StalenessBehavior: "stale model discovery evidence requires authenticated PTY refresh before capability promotion",
		Metadata:          map[string]any{"detail": snapshot.Detail},
	}
}

func snapshotFromDiscoveryRecord(rec cassette.DiscoveryRecord) harnesses.ModelDiscoverySnapshot {
	capturedAt, _ := time.Parse(time.RFC3339, rec.CapturedAt)
	detail, _ := rec.Metadata["detail"].(string)
	return harnesses.ModelDiscoverySnapshot{
		CapturedAt:      capturedAt,
		Models:          append([]string(nil), rec.Models...),
		ReasoningLevels: append([]string(nil), rec.ReasoningLevels...),
		Source:          rec.Source,
		FreshnessWindow: rec.FreshnessWindow,
		Detail:          detail,
	}
}

func uniqueMatches(values []string) []string {
	out := make([]string, 0, len(values))
	for _, value := range values {
		out = appendUniqueString(out, value)
	}
	return out
}

func appendUniqueString(values []string, value string) []string {
	value = strings.TrimSpace(value)
	if value == "" {
		return values
	}
	for _, existing := range values {
		if existing == value {
			return values
		}
	}
	return append(values, value)
}

package harnesses

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/easel/fizeau/internal/modelcatalog"
)

const EmbeddedDiscoverySource = "embedded-cassette"

type ModelDiscoveryLoader func(harnessName, source string) (ModelDiscoverySnapshot, error)

type discoveryCacheKey struct {
	harnessName string
	source      string
}

type discoveryCacheEntry struct {
	snapshot ModelDiscoverySnapshot
	err      error
}

// ModelDiscoveryCache memoizes in-process discovery snapshots by harness and
// source. The embedded source is populated from the registry's cassette-backed
// model lists; live PTY refresh is intentionally out of scope here.
type ModelDiscoveryCache struct {
	mu      sync.Mutex
	loader  ModelDiscoveryLoader
	entries map[discoveryCacheKey]discoveryCacheEntry
}

func NewModelDiscoveryCache(loader ModelDiscoveryLoader) *ModelDiscoveryCache {
	if loader == nil {
		loader = LoadEmbeddedModelDiscoverySnapshot
	}
	return &ModelDiscoveryCache{
		loader:  loader,
		entries: make(map[discoveryCacheKey]discoveryCacheEntry),
	}
}

func (c *ModelDiscoveryCache) Snapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
	if c == nil {
		c = NewModelDiscoveryCache(nil)
	}
	key := discoveryCacheKey{
		harnessName: strings.TrimSpace(harnessName),
		source:      strings.TrimSpace(source),
	}
	if key.source == "" {
		key.source = EmbeddedDiscoverySource
	}
	c.mu.Lock()
	if entry, ok := c.entries[key]; ok {
		c.mu.Unlock()
		return entry.snapshot, entry.err
	}
	loader := c.loader
	c.mu.Unlock()

	snapshot, err := loader(key.harnessName, key.source)

	c.mu.Lock()
	c.entries[key] = discoveryCacheEntry{snapshot: snapshot, err: err}
	c.mu.Unlock()
	return snapshot, err
}

var defaultDiscoveryCache = NewModelDiscoveryCache(nil)

func CachedModelDiscoverySnapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
	return defaultDiscoveryCache.Snapshot(harnessName, source)
}

func LoadEmbeddedModelDiscoverySnapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
	cfg, ok := NewRegistry().Get(harnessName)
	if !ok {
		return ModelDiscoverySnapshot{}, fmt.Errorf("unknown harness %q", harnessName)
	}
	if len(cfg.Models) == 0 {
		return ModelDiscoverySnapshot{}, fmt.Errorf("harness %q has no embedded model discovery snapshot", harnessName)
	}
	if source == "" {
		source = EmbeddedDiscoverySource
	}
	return ModelDiscoverySnapshot{
		CapturedAt:      time.Now().UTC(),
		Models:          append([]string(nil), cfg.Models...),
		ReasoningLevels: append([]string(nil), cfg.ReasoningLevels...),
		Source:          source,
		Detail:          "embedded registry snapshot refreshed by model-discovery cassette tests",
	}, nil
}

type RunnerModelResolution struct {
	HarnessName       string `json:"harness_name"`
	RequestedModel    string `json:"requested_model,omitempty"`
	ResolvedModel     string `json:"resolved_model"`
	PriorDefaultModel string `json:"prior_default_model,omitempty"`
	Source            string `json:"source"`
	Surface           string `json:"surface"`
	Warning           string `json:"warning,omitempty"`
	Reason            string `json:"reason,omitempty"`
	ExplicitPin       bool   `json:"explicit_pin,omitempty"`
}

type modelCandidate struct {
	model  string
	parsed modelcatalog.ParsedModel
	power  int
	order  int
}

func ResolveRunnerModel(harnessName string, surface modelcatalog.Surface, requestedModel, fallbackDefault string) RunnerModelResolution {
	return resolveRunnerModel(defaultDiscoveryCache, harnessName, surface, requestedModel, fallbackDefault)
}

func resolveRunnerModel(cache *ModelDiscoveryCache, harnessName string, surface modelcatalog.Surface, requestedModel, fallbackDefault string) RunnerModelResolution {
	resolution := RunnerModelResolution{
		HarnessName:       harnessName,
		RequestedModel:    requestedModel,
		PriorDefaultModel: fallbackDefault,
		Surface:           string(surface),
		Source:            EmbeddedDiscoverySource,
	}

	requestedModel = strings.TrimSpace(requestedModel)
	if requestedModel != "" {
		resolution.ResolvedModel = requestedModel
		resolution.ExplicitPin = true
		snapshot, err := cache.Snapshot(harnessName, EmbeddedDiscoverySource)
		if err != nil {
			resolution.Warning = fmt.Sprintf("model discovery unavailable for explicit pin validation: %v", err)
			resolution.Reason = "explicit_pin_discovery_unavailable"
			return resolution
		}
		resolution.Source = snapshot.Source
		if !stringInSliceFold(requestedModel, snapshot.Models) {
			resolution.Warning = fmt.Sprintf("explicit model pin %q was not present in %s snapshot", requestedModel, snapshot.Source)
			resolution.Reason = "explicit_pin_absent_from_snapshot"
		}
		return resolution
	}

	snapshot, err := cache.Snapshot(harnessName, EmbeddedDiscoverySource)
	if err != nil {
		resolution.ResolvedModel = fallbackDefault
		resolution.Warning = fmt.Sprintf("model discovery lookup failed; using fallback default %q: %v", fallbackDefault, err)
		resolution.Reason = "discovery_lookup_failed"
		return resolution
	}
	resolution.Source = snapshot.Source

	catalog, err := modelcatalog.Default()
	if err != nil {
		resolution.ResolvedModel = fallbackDefault
		resolution.Warning = fmt.Sprintf("model catalog load failed; using fallback default %q: %v", fallbackDefault, err)
		resolution.Reason = "catalog_load_failed"
		return resolution
	}

	candidates := autoRoutableSnapshotCandidates(catalog, snapshot, surface)
	if len(candidates) == 0 {
		resolution.ResolvedModel = fallbackDefault
		resolution.Warning = fmt.Sprintf("model discovery snapshot %s had no auto-routable catalog candidates; using fallback default %q", snapshot.Source, fallbackDefault)
		resolution.Reason = "no_auto_routable_discovery_candidate"
		return resolution
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		if cmp := candidates[i].parsed.Compare(candidates[j].parsed); cmp != 0 {
			return cmp < 0
		}
		if candidates[i].power != candidates[j].power {
			return candidates[i].power > candidates[j].power
		}
		return candidates[i].order < candidates[j].order
	})

	resolution.ResolvedModel = candidates[0].model
	if resolution.ResolvedModel != fallbackDefault {
		resolution.Reason = "discovery_default_changed"
	}
	return resolution
}

func autoRoutableSnapshotCandidates(catalog *modelcatalog.Catalog, snapshot ModelDiscoverySnapshot, surface modelcatalog.Surface) []modelCandidate {
	seen := make(map[string]bool)
	candidates := make([]modelCandidate, 0, len(snapshot.Models))
	for i, modelID := range snapshot.Models {
		modelID = strings.TrimSpace(modelID)
		if modelID == "" {
			continue
		}
		eligibility, ok := catalog.ModelEligibility(modelID)
		if !ok || !eligibility.AutoRoutable {
			continue
		}
		resolved, err := catalog.Resolve(modelID, modelcatalog.ResolveOptions{Surface: surface})
		if err != nil || resolved.ConcreteModel == "" {
			continue
		}
		if seen[resolved.ConcreteModel] {
			continue
		}
		seen[resolved.ConcreteModel] = true
		candidates = append(candidates, modelCandidate{
			model:  resolved.ConcreteModel,
			parsed: modelcatalog.Parse(resolved.ConcreteModel),
			power:  eligibility.Power,
			order:  i,
		})
	}
	return candidates
}

func stringInSliceFold(needle string, haystack []string) bool {
	for _, candidate := range haystack {
		if strings.EqualFold(strings.TrimSpace(candidate), needle) {
			return true
		}
	}
	return false
}

func RunnerDefaultResolutionEvent(resolution RunnerModelResolution, metadata map[string]string, seq *int64) Event {
	raw, err := json.Marshal(resolution)
	if err != nil {
		raw = []byte(`{"warning":"marshal runner default resolution"}`)
	}
	ev := Event{
		Type:     EventTypeRoutingDecision,
		Time:     time.Now().UTC(),
		Metadata: metadata,
		Data:     raw,
	}

	}
	if seq != nil {
		ev.Sequence = *seq
		*seq++
	}
	return ev
}

func ShouldEmitRunnerDefaultResolution(resolution RunnerModelResolution) bool {
	return resolution.Warning != "" ||
		(!resolution.ExplicitPin && resolution.PriorDefaultModel != "" && resolution.ResolvedModel != "" && resolution.ResolvedModel != resolution.PriorDefaultModel)
}

package harnesses

import (
	"testing"
	"time"

	"github.com/easel/fizeau/internal/modelcatalog"
)

func TestDiscoveryCacheSharedAcrossRunnerDefaultResolutions(t *testing.T) {
	loads := 0
	cache := NewModelDiscoveryCache(func(harnessName, source string) (ModelDiscoverySnapshot, error) {
		loads++
		if harnessName != "codex" {
			t.Fatalf("harnessName = %q, want codex", harnessName)
		}
		if source != EmbeddedDiscoverySource {
			t.Fatalf("source = %q, want %q", source, EmbeddedDiscoverySource)
		}
		return ModelDiscoverySnapshot{
			CapturedAt: time.Now().UTC(),
			Models:     []string{"gpt-5.5", "gpt-5.4"},
			Source:     source,
		}, nil
	})

	first := resolveRunnerModel(cache, "codex", modelcatalog.SurfaceCodex, "", "gpt-5.4")
	second := resolveRunnerModel(cache, "codex", modelcatalog.SurfaceCodex, "", "gpt-5.4")

	if first.ResolvedModel != "gpt-5.5" || second.ResolvedModel != "gpt-5.5" {
		t.Fatalf("resolved models: got %q and %q, want gpt-5.5", first.ResolvedModel, second.ResolvedModel)
	}
	if loads != 1 {
		t.Fatalf("snapshot loads = %d, want 1", loads)
	}
}

func TestResolveRunnerModelExplicitPinWins(t *testing.T) {
	cache := NewModelDiscoveryCache(func(harnessName, source string) (ModelDiscoverySnapshot, error) {
		return ModelDiscoverySnapshot{
			CapturedAt: time.Now().UTC(),
			Models:     []string{"gpt-5.5", "gpt-5.4"},
			Source:     source,
		}, nil
	})

	got := resolveRunnerModel(cache, "codex", modelcatalog.SurfaceCodex, "gpt-5.4", "gpt-5.4")
	if !got.ExplicitPin || got.ResolvedModel != "gpt-5.4" {
		t.Fatalf("resolution = %#v, want explicit gpt-5.4", got)
	}
}

