package session

import (
	"encoding/json"
	"time"

	agent "github.com/easel/fizeau/internal/core"
)

// SessionStartData is the data payload for a session.start event.
type SessionStartData struct {
	Provider               string                  `json:"provider"`
	Model                  string                  `json:"model"`
	SelectedProvider       string                  `json:"selected_provider,omitempty"`
	SelectedEndpoint       string                  `json:"selected_endpoint,omitempty"`
	SelectedServerInstance string                  `json:"selected_server_instance,omitempty"`
	SelectedRoute          string                  `json:"selected_route,omitempty"`
	Sticky                 RoutingStickyState      `json:"sticky,omitempty"`
	Utilization            RoutingUtilizationState `json:"utilization,omitempty"`
	RequestedHarness       string                  `json:"requested_harness,omitempty"`
	ResolvedHarness        string                  `json:"resolved_harness,omitempty"`
	HarnessSource          string                  `json:"harness_source,omitempty"`
	RequestedModel         string                  `json:"requested_model,omitempty"`
	ResolvedModel          string                  `json:"resolved_model,omitempty"`
	Reasoning              agent.Reasoning         `json:"reasoning,omitempty"`
	AttemptedProviders     []string                `json:"attempted_providers,omitempty"`
	FailoverCount          int                     `json:"failover_count,omitempty"`
	WorkDir                string                  `json:"work_dir"`
	MaxIterations          int                     `json:"max_iterations"`
	Prompt                 string                  `json:"prompt"`
	SystemPrompt           string                  `json:"system_prompt,omitempty"`
	Metadata               map[string]string       `json:"metadata,omitempty"`
}

// LLMRequestData is the data payload for an llm.request event.
type LLMRequestData struct {
	Messages          []agent.Message `json:"messages"`
	Tools             []agent.ToolDef `json:"tools,omitempty"`
	Model             string          `json:"model,omitempty"`
	Temperature       *float64        `json:"temperature,omitempty"`
	TopP              *float64        `json:"top_p,omitempty"`
	TopK              *int            `json:"top_k,omitempty"`
	MinP              *float64        `json:"min_p,omitempty"`
	RepetitionPenalty *float64        `json:"repetition_penalty,omitempty"`
	MaxTokens         int             `json:"max_tokens,omitempty"`
	Seed              int64           `json:"seed,omitempty"`
	Stop              []string        `json:"stop,omitempty"`
	Reasoning         agent.Reasoning `json:"reasoning,omitempty"`
	CachePolicy       string          `json:"cache_policy,omitempty"`
	// SamplingSource is the comma-separated list of resolution layers that
	// supplied non-nil sampler fields, in chain order. Values:
	// "catalog", "provider_config", "cli", or combinations like
	// "catalog,provider_config". Empty when all sampler fields were nil
	// (server defaults applied). See ADR-007 §5.
	SamplingSource string `json:"sampling_source,omitempty"`
}

// LLMResponseData is the data payload for an llm.response event.
type LLMResponseData struct {
	Content      string           `json:"content,omitempty"`
	ToolCalls    []agent.ToolCall `json:"tool_calls,omitempty"`
	Usage        agent.TokenUsage `json:"usage"`
	CostUSD      float64          `json:"cost_usd"`
	LatencyMs    int64            `json:"latency_ms"`
	Model        string           `json:"model"`
	FinishReason string           `json:"finish_reason"`
}

// ToolCallData is the data payload for a tool.call event.
type ToolCallData struct {
	Tool       string          `json:"tool"`
	Input      json.RawMessage `json:"input"`
	Output     string          `json:"output"`
	DurationMs int64           `json:"duration_ms"`
	Error      string          `json:"error,omitempty"`
}

// SessionEndData is the data payload for a session.end event.
type SessionEndData struct {
	Status                 agent.Status            `json:"status"`
	Output                 string                  `json:"output"`
	Tokens                 agent.TokenUsage        `json:"tokens"`
	CostUSD                *float64                `json:"cost_usd,omitempty"`
	DurationMs             int64                   `json:"duration_ms"`
	Model                  string                  `json:"model,omitempty"`
	SelectedProvider       string                  `json:"selected_provider,omitempty"`
	SelectedEndpoint       string                  `json:"selected_endpoint,omitempty"`
	SelectedServerInstance string                  `json:"selected_server_instance,omitempty"`
	SelectedRoute          string                  `json:"selected_route,omitempty"`
	Sticky                 RoutingStickyState      `json:"sticky,omitempty"`
	Utilization            RoutingUtilizationState `json:"utilization,omitempty"`
	RequestedHarness       string                  `json:"requested_harness,omitempty"`
	ResolvedHarness        string                  `json:"resolved_harness,omitempty"`
	HarnessSource          string                  `json:"harness_source,omitempty"`
	RequestedModel         string                  `json:"requested_model,omitempty"`
	ResolvedModel          string                  `json:"resolved_model,omitempty"`
	Reasoning              agent.Reasoning         `json:"reasoning,omitempty"`
	AttemptedProviders     []string                `json:"attempted_providers,omitempty"`
	FailoverCount          int                     `json:"failover_count,omitempty"`
	Metadata               map[string]string       `json:"metadata,omitempty"`
	Error                  string                  `json:"error,omitempty"`
	// ProcessOutcome surfaces the FEAT-005 §27 / SD-010 failure-taxonomy
	// label for terminal events that map to a first-class outcome
	// distinct from Status (e.g. "budget_halted"). Empty when no outcome
	// label applies — Status alone is then authoritative.
	ProcessOutcome string `json:"process_outcome,omitempty"`
	// CostCapUSD echoes the per-run cost cap (when configured) onto the
	// session.end record so post-hoc tooling can report cost-vs-cap without
	// reading the run's request envelope. Zero or nil when no cap was set.
	CostCapUSD *float64 `json:"cost_cap_usd,omitempty"`
}

// RoutingStickyState summarizes sticky routing behavior without exposing
// the raw sticky key.
type RoutingStickyState struct {
	KeyPresent     bool    `json:"key_present,omitempty"`
	Assignment     string  `json:"assignment,omitempty"`
	ServerInstance string  `json:"server_instance,omitempty"`
	Reason         string  `json:"reason,omitempty"`
	Bonus          float64 `json:"bonus"`
}

// RoutingUtilizationState carries the live endpoint sample that informed a
// routing decision.
type RoutingUtilizationState struct {
	Source         string    `json:"source,omitempty"`
	Freshness      string    `json:"freshness,omitempty"`
	ActiveRequests *int      `json:"active_requests,omitempty"`
	QueuedRequests *int      `json:"queued_requests,omitempty"`
	MaxConcurrency *int      `json:"max_concurrency,omitempty"`
	CachePressure  *float64  `json:"cache_pressure,omitempty"`
	ObservedAt     time.Time `json:"observed_at,omitempty"`
}

// NewEvent creates an Event with the given type and data, auto-assigning
// the timestamp.
func NewEvent(sessionID string, seq int, eventType agent.EventType, data any) agent.Event {
	raw, _ := json.Marshal(data)
	return agent.Event{
		SessionID: sessionID,
		Seq:       seq,
		Type:      eventType,
		Timestamp: time.Now().UTC(),
		Data:      raw,
	}
}

package serviceimpl

import (
	"context"
	"encoding/json"
	"time"

	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/reasoning"
)

// SubprocessRequest is the API-neutral request data needed by subprocess
// harness runner implementations.
type SubprocessRequest struct {
	Prompt         string
	SystemPrompt   string
	WorkDir        string
	Permissions    string
	Temperature    *float32
	Seed           *int64
	Reasoning      reasoning.Reasoning
	Timeout        time.Duration
	IdleTimeout    time.Duration
	SessionLogDir  string
	Metadata       map[string]string
	Decision       ExecuteRunnerDecision
	Started        time.Time
	SessionLogPath string
}

// SubprocessCallbacks bridge service-owned event/progress/session-log behavior
// without importing root public service types.
type SubprocessCallbacks struct {
	BeforeExecute func()
	BeforeFinal   func(harnesses.FinalData)
	ObserveEvent  func(harnesses.Event) harnesses.Event
	EmitEvent     func(harnesses.Event) bool
	Finalize      func(harnesses.FinalData)
	WriteEnd      func(map[string]string, harnesses.FinalData)
}

// RunSubprocess executes a subprocess harness and forwards its event stream.
func RunSubprocess(ctx context.Context, req SubprocessRequest, runner harnesses.Harness, cb SubprocessCallbacks) {
	hReq := harnesses.ExecuteRequest{
		Prompt:        req.Prompt,
		SystemPrompt:  req.SystemPrompt,
		Provider:      req.Decision.Provider,
		Model:         req.Decision.Model,
		WorkDir:       req.WorkDir,
		Permissions:   req.Permissions,
		Temperature:   subprocessTemperature(req.Temperature),
		Seed:          subprocessSeed(req.Seed),
		Reasoning:     adapterReasoning(req.Reasoning),
		Timeout:       req.Timeout,
		IdleTimeout:   req.IdleTimeout,
		SessionLogDir: req.SessionLogDir,
		Metadata:      req.Metadata,
	}
	if cb.BeforeExecute != nil {
		cb.BeforeExecute()
	}
	in, err := runner.Execute(ctx, hReq)
	if err != nil {
		finalizeSubprocess(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      err.Error(),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:        req.Decision.Harness,
				Provider:       req.Decision.Provider,
				ServerInstance: req.Decision.ServerInstance,
				Model:          req.Decision.Model,
			},
		})
		return
	}
	for ev := range in {
		if ev.Metadata == nil {
			ev.Metadata = req.Metadata
		}
		if ev.Type == harnesses.EventTypeFinal {
			var final harnesses.FinalData
			if err := json.Unmarshal(ev.Data, &final); err == nil && cb.BeforeFinal != nil {
				cb.BeforeFinal(final)
			}
			ev = stampSubprocessFinalRouting(ev, req.Decision)
			ev = stampSubprocessFinalSessionLog(ev, req.SessionLogPath)
			if err := json.Unmarshal(ev.Data, &final); err == nil && cb.WriteEnd != nil {
				cb.WriteEnd(req.Metadata, final)
			}
		}
		if cb.ObserveEvent != nil {
			ev = cb.ObserveEvent(ev)
		}
		if cb.EmitEvent != nil && !cb.EmitEvent(ev) {
			return
		}
	}
}

func subprocessTemperature(v *float32) float32 {
	if v == nil {
		return 0
	}
	return *v
}

func subprocessSeed(v *int64) int64 {
	if v == nil {
		return 0
	}
	return *v
}

func adapterReasoning(value reasoning.Reasoning) string {
	policy, err := reasoning.ParseString(string(value))
	if err != nil {
		return string(value)
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return ""
	case reasoning.KindTokens:
		if policy.Tokens == 0 {
			return ""
		}
		return string(policy.Value)
	case reasoning.KindNamed:
		return string(policy.Value)
	default:
		return string(value)
	}
}

func stampSubprocessFinalSessionLog(ev harnesses.Event, sessionLogPath string) harnesses.Event {
	if sessionLogPath == "" {
		return ev
	}
	var final harnesses.FinalData
	if err := json.Unmarshal(ev.Data, &final); err != nil {
		return ev
	}
	final.SessionLogPath = sessionLogPath
	raw, err := json.Marshal(final)
	if err != nil {
		return ev
	}
	ev.Data = raw
	return ev
}

func stampSubprocessFinalRouting(ev harnesses.Event, decision ExecuteRunnerDecision) harnesses.Event {
	var final harnesses.FinalData
	if err := json.Unmarshal(ev.Data, &final); err != nil {
		return ev
	}
	if final.RoutingActual == nil {
		final.RoutingActual = &harnesses.RoutingActual{
			Harness:        decision.Harness,
			Provider:       decision.Provider,
			ServerInstance: decision.ServerInstance,
			Model:          decision.Model,
		}
	}
	raw, err := json.Marshal(final)
	if err != nil {
		return ev
	}
	ev.Data = raw
	return ev
}

func finalizeSubprocess(cb SubprocessCallbacks, final harnesses.FinalData) {
	if cb.Finalize != nil {
		cb.Finalize(final)
	}
}

